package net.officefloor.hq.app.access;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.person.Person;

/**
 * A sheet's dated settings: each key's value in force on a date is the one with the latest from-date on or before it;
 * before every from-date, the key's starting value (see {@link Setting#starting}).
 */
public record DatedSettings(List<DatedValue> values) {

    /** The key's value in force on the date; null when blank. */
    public String on(String key, LocalDate date) {
        DatedValue found = null;
        for (DatedValue v : values) {
            if (v.key().equals(key) && !v.from().isAfter(date) && (found == null || v.from().isAfter(found.from()))) {
                found = v;
            }
        }
        return found == null ? Setting.starting(key) : found.value();
    }

    /** The floor in force on the date: the least a claim's live due may be. */
    public BigDecimal floor(LocalDate date) {
        return new BigDecimal(orStarting(Setting.FLOOR, date)).setScale(2);
    }

    /** The late percent in force on the date. */
    public BigDecimal latePct(LocalDate date) {
        return new BigDecimal(orStarting(Setting.LATE_PCT, date)).setScale(2);
    }

    /** The terms of the grade in force on the date: its own (setting terms-<grade>), else the sheet's. */
    public int terms(String grade, LocalDate date) {
        String value = grade == null ? null : on(Setting.TERMS_OF_GRADE + grade, date);
        return Integer.parseInt(value == null ? orStarting(Setting.TERMS, date) : value);
    }

    /** The terms in force on the date for the person: their own, else their grade's on that date, else the sheet's. */
    public int terms(Person person, LocalDate date) {
        if (person != null && person.getTerms() != null) {
            return person.getTerms();
        }
        return terms(person == null ? null : person.gradeOn(date), date);
    }

    /** The grace of the grade in force on the date (setting grace-<grade>): the days past its due-by a claim goes overdue; 0 while blank. */
    public int grace(String grade, LocalDate date) {
        String value = grade == null ? null : on(Setting.GRACE_OF_GRADE + grade, date);
        return value == null ? 0 : Integer.parseInt(value);
    }

    /** The clerk limit in force on the date; null when there is none. */
    public BigDecimal clerkLimit(LocalDate date) {
        String value = on(Setting.CLERK_LIMIT, date);
        return value == null ? null : new BigDecimal(value);
    }

    /** The proof threshold in force on the date; null when there is none. */
    public BigDecimal proofThreshold(LocalDate date) {
        String value = on(Setting.PROOF_THRESHOLD, date);
        return value == null ? null : new BigDecimal(value).setScale(2);
    }

    /** The proof threshold in force on the date for a claim of the grade: the grade's own (setting proof-threshold-<grade>) when set, else the sheet's; null when there is none. */
    public BigDecimal proofThreshold(String grade, LocalDate date) {
        String value = grade == null ? null : on(Setting.PROOF_THRESHOLD_OF_GRADE + grade, date);
        return value == null ? proofThreshold(date) : new BigDecimal(value).setScale(2);
    }

    /** The note threshold in force on the date; null when there is none. */
    public BigDecimal noteThreshold(LocalDate date) {
        String value = on(Setting.NOTE_THRESHOLD, date);
        return value == null ? null : new BigDecimal(value).setScale(2);
    }

    /** The cap in force on the date: the most a person's due-total may be; null when there is none. */
    public BigDecimal cap(LocalDate date) {
        String value = on(Setting.CAP, date);
        return value == null ? null : new BigDecimal(value).setScale(2);
    }

    private String orStarting(String key, LocalDate date) {
        String value = on(key, date);
        return value == null ? Setting.starting(key) : value;
    }
}
package net.officefloor.hq.app.access;

/** A setting on a sheet: its key and value (null: blank), and the from-date it was saved from when one was given (null otherwise). */
public record Setting(String sheetId, String key, String value, java.time.LocalDate from) {

    /** Whether the key's setting is dated: one that carries a figure (every key but the policy date, period numbering from, the entry date, the grace days, the fiscal start month, the pot, the alert threshold, the parent and the permissions). */
    public static boolean isDated(String key) {
        return !POLICY_DATE.equals(key) && !POT.equals(key) && !ALERT_THRESHOLD.equals(key) && !PARENT.equals(key) && !PERIOD_NUMBERING_FROM.equals(key) && !ENTRY_DATE.equals(key) && !GRACE_DAYS.equals(key) && !FISCAL_START_MONTH.equals(key) && !isPermission(key);
    }

    /** Whether the key is one of the permission matrix's (perm-<action>). */
    public static boolean isPermission(String key) {
        return key.startsWith(PERMISSION) && PERMISSION_STANDING.containsKey(key.substring(PERMISSION.length()));
    }

    /** The value a dated key has before every from-date: the floor's, the terms' and the late percent's starting value; null (blank) for the rest. */
    public static String starting(String key) {
        return switch (key) {
            case FLOOR -> FLOOR_DEFAULT;
            case TERMS -> TERMS_DEFAULT;
            case LATE_PCT -> LATE_PCT_DEFAULT;
            default -> null;
        };
    }

    /** The most a clerk may settle a claim's due for; blank means no limit. */
    public static final String CLERK_LIMIT = "clerk-limit";

    /** The due above which a claim needs a proof before it is settled or approved; blank means none. */
    public static final String PROOF_THRESHOLD = "proof-threshold";

    /** A grade's own proof threshold (the key is this plus the grade, proof-threshold-A); blank means the sheet's. */
    public static final String PROOF_THRESHOLD_OF_GRADE = "proof-threshold-";

    /** The due above which a claim needs a note before it is opened; blank means none. */
    public static final String NOTE_THRESHOLD = "note-threshold";

    /** The due-total above which a person crossing it writes an ALERT line; an amount with two decimals, blank for off. Not dated. */
    public static final String ALERT_THRESHOLD = "alert-threshold";

    /** The most a person's due-total may be; an amount with two decimals, blank for none. */
    public static final String CAP = "cap";

    /** The sheet's parent: the id of a sheet whose rates (then its parent's, up to three levels up) stand in for a grade without a rate in force on a date; blank for none. */
    public static final String PARENT = "parent";

    /** The sheet's pot: the pot of each pool that is a member of none, cut among its members by their shares when it is balanced (a member pool's cut is its own pot); an amount with two decimals, blank for none. */
    public static final String POT = "pot";

    /** The least a claim's live due may be; an amount with two decimals. */
    public static final String FLOOR = "floor";

    /** The floor a sheet starts with, until it is set. */
    public static final String FLOOR_DEFAULT = "1.00";

    /** The number of days after its date a claim is due by; a whole number. */
    public static final String TERMS = "terms";

    /** The terms a sheet starts with, until they are set. */
    public static final String TERMS_DEFAULT = "14";

    /** A grade's own terms (the key is this plus the grade, terms-A); blank means the sheet's terms. */
    public static final String TERMS_OF_GRADE = "terms-";

    /** A grade's grace (the key is this plus the grade, grace-A): the days past its due-by a claim of that grade on its date goes overdue and counts its late charge from; blank means none. */
    public static final String GRACE_OF_GRADE = "grace-";

    /** The grades that may have their own terms, grace and proof threshold. */
    public static final java.util.Set<String> GRADES = java.util.Set.of("A", "B", "C");

    /** The percent of its figure an overdue claim's due gains for every full 30 days it is overdue, the one in force on each 30-day boundary date; two decimals. */
    public static final String LATE_PCT = "late-pct";

    /** The late percent a sheet starts with, until it is set. */
    public static final String LATE_PCT_DEFAULT = "0.00";

    /** The date before which a claim's live figures round half up, and from which half to even; blank means the sheet's today. */
    public static final String POLICY_DATE = "policy-date";

    /** The date from which (on the sheet's today) an opened claim is numbered within its period; blank means off. */
    public static final String PERIOD_NUMBERING_FROM = "period-numbering-from";

    /** The default date of a new claim (the claim form, the quick-add bar, a pasted line, a correction) in place of the sheet's today; blank means off. */
    public static final String ENTRY_DATE = "entry-date";

    /** The days after its to-date an open period is closed by itself when the sheet's today moves past them; a whole number, blank for off. */
    public static final String GRACE_DAYS = "grace-days";

    /** The month (1 to 12) the sheet's fiscal year starts in; 1 until it is set. */
    public static final String FISCAL_START_MONTH = "fiscal-start-month";

    /** The fiscal start month a sheet starts with, until it is set. */
    public static final int FISCAL_START_MONTH_DEFAULT = 1;

    /** The roles that may take an action (the key is this plus the action, perm-open): a comma separated list of roles, blank for the standing rule. */
    public static final String PERMISSION = "perm-";

    /** Each action's standing rule, the roles that may take it while its permission is blank. */
    public static final java.util.Map<String, java.util.List<String>> PERMISSION_STANDING = java.util.Map.of(
            "open", java.util.List.of(Role.CLERK, Role.STEWARD),
            "settle", java.util.List.of(Role.CLERK, Role.STEWARD),
            "void", java.util.List.of(Role.CLERK, Role.STEWARD),
            "close", java.util.List.of(Role.CLERK, Role.STEWARD),
            "reassign", java.util.List.of(Role.STEWARD),
            "reopen", java.util.List.of(Role.STEWARD));
}
package net.officefloor.hq.app.access;

import java.math.BigDecimal;
import java.util.regex.Pattern;
import net.officefloor.hq.app.BadRequestException;
import net.officefloor.hq.app.session.ChangedBy;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** A setting's fields: a known key, its value, and for a dated setting an optional from-date (yyyy-mm-dd). The terms are a whole number of days. A grade's terms (terms-<grade>) are a whole number of days, or blank for the sheet's terms. A grade's grace (grace-<grade>) is a whole number of days, or blank for none. The floor is an amount with up to two decimals. The clerk limit is an amount with up to two decimals, or blank for no limit. The late percent is a number with up to two decimals. The policy date is a date (yyyy-mm-dd), or blank for the sheet's today. Period numbering from is a date, or blank for off. The entry date is a date, or blank for off. The grace days are a whole number of days, or blank for off. The cap is an amount with up to two decimals, or blank for none. The proof threshold is an amount with up to two decimals, or blank for none. A grade's proof threshold (proof-threshold-<grade>) is an amount with up to two decimals, or blank for the sheet's. The note threshold is an amount with up to two decimals, or blank for none. The pot is an amount with up to two decimals, or blank for none. The alert threshold is an amount with up to two decimals, or blank for off. The parent is a sheet id, or blank for none. A permission (perm-<action>) is a comma separated list of roles, or blank for the standing rule. */
public class ValidateSetting {

    private static final Pattern AMOUNT = Pattern.compile("\\d{1,10}(\\.\\d{1,2})?");
    private static final Pattern DAYS = Pattern.compile("\\d{1,5}");
    private static final Pattern MONTH = Pattern.compile("\\d{1,2}");

    public void validate(@RequestBody SettingRequest request, Out<SettingInput> setting, Out<ChangedBy> changedBy)
            throws BadRequestException {
        ChangedBy by = ChangedBy.of(request == null ? null : request.by());
        String key = request == null || request.key() == null ? "" : request.key().trim();
        String text = request == null || request.value() == null ? "" : request.value().trim();
        String fromText = request == null || request.from() == null ? "" : request.from().trim();
        java.time.LocalDate from = null;
        if (!fromText.isEmpty()) {
            if (!Setting.isDated(key)) {
                throw new BadRequestException("The " + key + " setting is not dated; leave its from-date blank");
            }
            try {
                from = java.time.LocalDate.parse(fromText);
            } catch (java.time.format.DateTimeParseException e) {
                throw new BadRequestException("A from-date is a date (yyyy-mm-dd), or blank for the sheet's today");
            }
        }
        if (Setting.TERMS.equals(key)) {
            if (!DAYS.matcher(text).matches()) {
                throw new BadRequestException("Terms are a whole number of days");
            }
            setting.set(new SettingInput(key, String.valueOf(Integer.parseInt(text)), from));
            changedBy.set(by);
            return;
        }
        if (key.startsWith(Setting.TERMS_OF_GRADE) && Setting.GRADES.contains(key.substring(Setting.TERMS_OF_GRADE.length()))) {
            if (!text.isEmpty() && !DAYS.matcher(text).matches()) {
                throw new BadRequestException("A grade's terms are a whole number of days, or blank for the sheet's terms");
            }
            setting.set(new SettingInput(key, text.isEmpty() ? null : String.valueOf(Integer.parseInt(text)), from));
            changedBy.set(by);
            return;
        }
        if (key.startsWith(Setting.GRACE_OF_GRADE) && Setting.GRADES.contains(key.substring(Setting.GRACE_OF_GRADE.length()))) {
            if (!text.isEmpty() && !DAYS.matcher(text).matches()) {
                throw new BadRequestException("A grade's grace is a whole number of days, or blank for none");
            }
            setting.set(new SettingInput(key, text.isEmpty() ? null : String.valueOf(Integer.parseInt(text)), from));
            changedBy.set(by);
            return;
        }
        if (Setting.FLOOR.equals(key)) {
            if (!AMOUNT.matcher(text).matches()) {
                throw new BadRequestException("A floor is an amount with up to two decimals");
            }
            setting.set(new SettingInput(key, new BigDecimal(text).setScale(2).toPlainString(), from));
            changedBy.set(by);
            return;
        }
        if (Setting.LATE_PCT.equals(key)) {
            if (!AMOUNT.matcher(text).matches()) {
                throw new BadRequestException("A late percent is a number with up to two decimals");
            }
            setting.set(new SettingInput(key, new BigDecimal(text).setScale(2).toPlainString(), from));
            changedBy.set(by);
            return;
        }
        if (Setting.POLICY_DATE.equals(key)) {
            String date = null;
            if (!text.isEmpty()) {
                try {
                    date = java.time.LocalDate.parse(text).toString();
                } catch (java.time.format.DateTimeParseException e) {
                    throw new BadRequestException("A policy date is a date (yyyy-mm-dd), or blank for the sheet's today");
                }
            }
            setting.set(new SettingInput(key, date, from));
            changedBy.set(by);
            return;
        }
        if (Setting.PERIOD_NUMBERING_FROM.equals(key)) {
            String date = null;
            if (!text.isEmpty()) {
                try {
                    date = java.time.LocalDate.parse(text).toString();
                } catch (java.time.format.DateTimeParseException e) {
                    throw new BadRequestException("Period numbering from is a date (yyyy-mm-dd), or blank for off");
                }
            }
            setting.set(new SettingInput(key, date, from));
            changedBy.set(by);
            return;
        }
        if (Setting.ENTRY_DATE.equals(key)) {
            String date = null;
            if (!text.isEmpty()) {
                try {
                    date = java.time.LocalDate.parse(text).toString();
                } catch (java.time.format.DateTimeParseException e) {
                    throw new BadRequestException("An entry date is a date (yyyy-mm-dd), or blank for off");
                }
            }
            setting.set(new SettingInput(key, date, from));
            changedBy.set(by);
            return;
        }
        if (Setting.GRACE_DAYS.equals(key)) {
            if (!text.isEmpty() && !DAYS.matcher(text).matches()) {
                throw new BadRequestException("Grace days are a whole number of days, or blank for off");
            }
            setting.set(new SettingInput(key, text.isEmpty() ? null : String.valueOf(Integer.parseInt(text)), from));
            changedBy.set(by);
            return;
        }
        if (Setting.FISCAL_START_MONTH.equals(key)) {
            if (!MONTH.matcher(text).matches() || Integer.parseInt(text) < 1 || Integer.parseInt(text) > 12) {
                throw new BadRequestException("A fiscal start month is a month from 1 to 12");
            }
            setting.set(new SettingInput(key, String.valueOf(Integer.parseInt(text)), from));
            changedBy.set(by);
            return;
        }
        if (Setting.CAP.equals(key)) {
            String value = null;
            if (!text.isEmpty()) {
                if (!AMOUNT.matcher(text).matches()) {
                    throw new BadRequestException("A cap is an amount with up to two decimals, or blank for none");
                }
                value = new BigDecimal(text).setScale(2).toPlainString();
            }
            setting.set(new SettingInput(key, value, from));
            changedBy.set(by);
            return;
        }
        if (Setting.PROOF_THRESHOLD.equals(key)) {
            String value = null;
            if (!text.isEmpty()) {
                if (!AMOUNT.matcher(text).matches()) {
                    throw new BadRequestException("A proof threshold is an amount with up to two decimals, or blank for none");
                }
                value = new BigDecimal(text).setScale(2).toPlainString();
            }
            setting.set(new SettingInput(key, value, from));
            changedBy.set(by);
            return;
        }
        if (key.startsWith(Setting.PROOF_THRESHOLD_OF_GRADE)
                && Setting.GRADES.contains(key.substring(Setting.PROOF_THRESHOLD_OF_GRADE.length()))) {
            String value = null;
            if (!text.isEmpty()) {
                if (!AMOUNT.matcher(text).matches()) {
                    throw new BadRequestException("A grade's proof threshold is an amount with up to two decimals, or blank for the sheet's");
                }
                value = new BigDecimal(text).setScale(2).toPlainString();
            }
            setting.set(new SettingInput(key, value, from));
            changedBy.set(by);
            return;
        }
        if (Setting.NOTE_THRESHOLD.equals(key)) {
            String value = null;
            if (!text.isEmpty()) {
                if (!AMOUNT.matcher(text).matches()) {
                    throw new BadRequestException("A note threshold is an amount with up to two decimals, or blank for none");
                }
                value = new BigDecimal(text).setScale(2).toPlainString();
            }
            setting.set(new SettingInput(key, value, from));
            changedBy.set(by);
            return;
        }
        if (Setting.ALERT_THRESHOLD.equals(key)) {
            String value = null;
            if (!text.isEmpty()) {
                if (!AMOUNT.matcher(text).matches()) {
                    throw new BadRequestException("An alert threshold is an amount with up to two decimals, or blank for off");
                }
                value = new BigDecimal(text).setScale(2).toPlainString();
            }
            setting.set(new SettingInput(key, value, from));
            changedBy.set(by);
            return;
        }
        if (Setting.POT.equals(key)) {
            String value = null;
            if (!text.isEmpty()) {
                if (!AMOUNT.matcher(text).matches()) {
                    throw new BadRequestException("A pot is an amount with up to two decimals, or blank for none");
                }
                value = new BigDecimal(text).setScale(2).toPlainString();
            }
            setting.set(new SettingInput(key, value, from));
            changedBy.set(by);
            return;
        }
        if (Setting.PARENT.equals(key)) {
            if (text.length() > 200) {
                throw new BadRequestException("A parent is a sheet id, or blank for none");
            }
            setting.set(new SettingInput(key, text.isEmpty() ? null : text, from));
            changedBy.set(by);
            return;
        }
        if (Setting.isPermission(key)) {
            String value = null;
            if (!text.isEmpty()) {
                java.util.List<String> roles = java.util.Arrays.stream(text.split(",", -1)).map(String::trim).toList();
                if (roles.stream().anyMatch(r -> !r.equals(Role.CLERK) && !r.equals(Role.STEWARD))) {
                    throw new BadRequestException("A permission is a comma separated list of roles (clerk, steward), or blank for the standing rule");
                }
                value = String.join(",", roles);
            }
            setting.set(new SettingInput(key, value, from));
            changedBy.set(by);
            return;
        }
        if (!Setting.CLERK_LIMIT.equals(key)) {
            throw new BadRequestException("No such setting: " + key);
        }
        String value = null;
        if (!text.isEmpty()) {
            if (!AMOUNT.matcher(text).matches()) {
                throw new BadRequestException("A clerk limit is an amount with up to two decimals, or blank for no limit");
            }
            value = new BigDecimal(text).setScale(2).toPlainString();
        }
        setting.set(new SettingInput(key, value, from));
        changedBy.set(by);
    }
}
package net.officefloor.hq.app.access;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.stereotype.Repository;

/**
 * The settings on each sheet, by key; a key without a row is blank. A dated setting (see {@link Setting#isDated}) keeps
 * every value saved, each from its from-date; the one in force on a date is the latest from on or before it (see
 * {@link DatedSettings}).
 */
@Repository
public class SettingRepository {

    private static final RowMapper<Setting> ROW = (rs, n) -> new Setting(rs.getString("sheet_id"),
            rs.getString("setting_key"), rs.getString("setting_value"), null);

    private static final RowMapper<DatedValue> DATED = (rs, n) -> new DatedValue(rs.getString("setting_key"),
            rs.getObject("from_date", LocalDate.class), rs.getString("setting_value"));

    private final JdbcTemplate jdbc;
    private final PersonRepository people;

    /** Settings over the connection, with its people (a past view of the sheet reads both as they were). */
    public SettingRepository(JdbcTemplate jdbc) {
        this(jdbc, new PersonRepository(jdbc));
    }

    @org.springframework.beans.factory.annotation.Autowired
    public SettingRepository(JdbcTemplate jdbc, PersonRepository people) {
        this.jdbc = jdbc;
        this.people = people;
    }

    /** The sheet's undated settings, by key (the policy date, period numbering from, the entry date, the grace days, the pot and the permissions); a key without a row is not listed. */
    public List<Setting> listUndated(String sheetId) {
        return jdbc.query("SELECT sheet_id, setting_key, setting_value FROM sheet_setting WHERE sheet_id = ?"
                + " ORDER BY setting_key", ROW, sheetId);
    }

    /** The sheet's dated settings: every value recorded, by key and from-date. */
    public DatedSettings dated(String sheetId) {
        return new DatedSettings(jdbc.query("SELECT setting_key, from_date, setting_value FROM sheet_setting_from"
                + " WHERE sheet_id = ? ORDER BY setting_key, from_date", DATED, sheetId));
    }

    /** The undated setting's value; null when blank. */
    public String find(String sheetId, String key) {
        return jdbc.query("SELECT sheet_id, setting_key, setting_value FROM sheet_setting WHERE sheet_id = ?"
                + " AND setting_key = ?", ROW, sheetId, key).stream().findFirst().map(Setting::value).orElse(null);
    }

    /** Whether the role may take the action (open, settle, void, reassign, close, reopen): its permission's roles, else the standing rule. */
    public boolean allows(String sheetId, String action, String role) {
        String value = find(sheetId, Setting.PERMISSION + action);
        List<String> roles = value == null ? Setting.PERMISSION_STANDING.get(action) : List.of(value.split(","));
        return roles.contains(role);
    }

    /** A person's due-total held to the cap: the cap when it is above it; n/a (null) and no cap leave it as it is. */
    public static BigDecimal capped(BigDecimal dueTotal, BigDecimal cap) {
        return dueTotal == null || cap == null || dueTotal.compareTo(cap) <= 0 ? dueTotal : cap;
    }

    /** The sheet's policy date: the one set, else its today. */
    public LocalDate policyDate(String sheetId, LocalDate today) {
        String value = find(sheetId, Setting.POLICY_DATE);
        return value == null ? today : LocalDate.parse(value);
    }

    /** The sheet's period numbering from-date; null while off. */
    public LocalDate periodNumberingFrom(String sheetId) {
        String value = find(sheetId, Setting.PERIOD_NUMBERING_FROM);
        return value == null ? null : LocalDate.parse(value);
    }

    /** The date a new claim with a blank date takes: the sheet's entry date while set, else its today. */
    public LocalDate entryDate(String sheetId, LocalDate today) {
        String value = find(sheetId, Setting.ENTRY_DATE);
        return value == null ? today : LocalDate.parse(value);
    }

    /** The sheet's grace days; null while off. */
    public Integer graceDays(String sheetId) {
        String value = find(sheetId, Setting.GRACE_DAYS);
        return value == null ? null : Integer.valueOf(value);
    }

    /** The month (1 to 12) the sheet's fiscal year starts in; 1 until it is set. */
    public int fiscalStartMonth(String sheetId) {
        String value = find(sheetId, Setting.FISCAL_START_MONTH);
        return value == null ? Setting.FISCAL_START_MONTH_DEFAULT : Integer.parseInt(value);
    }

    /** The sheet's late charge as of its today, each 30-day boundary's late percent the one in force on its date, with its policy date for rounding and its people for each claim's grade's grace. */
    public LateCharge lateCharge(String sheetId, LocalDate today) {
        java.util.Map<Long, Person> byId = new java.util.HashMap<>();
        people.list(sheetId).forEach(p -> byId.put(p.getId(), p));
        return new LateCharge(today, dated(sheetId), policyDate(sheetId, today), byId);
    }

    /** Set an undated setting's value (null: blank), replacing the one there before. */
    public Setting set(String sheetId, String key, String value) {
        jdbc.update("MERGE INTO sheet_setting (sheet_id, setting_key, setting_value) KEY (sheet_id, setting_key)"
                + " VALUES (?, ?, ?)", sheetId, key, value);
        return new Setting(sheetId, key, value, null);
    }

    /** Record a dated setting's value (null: blank) from the date, keeping the others; one already from that date is replaced. */
    public void setFrom(String sheetId, String key, LocalDate from, String value) {
